const results = await Promise.allSettled([
tools.exec_command({cmd:"pwd && git status --short && git branch --show-current && git remote -v && git ls-files && ls -la","max_output_tokens":6000}),
tools.exec_command({cmd:"entire agent-help","max_output_tokens":3000}),
tools.exec_command({cmd:"cat /Users/rizelscarlett/.codex/skills/using-entire/SKILL.md","max_output_tokens":4000}),
tools.web__run({open:[{ref_id:"https://github.com/aaif-goose/goosetown"}],response_length:"long"})
]); results.forEach((r,i)=>text({i,...r}));

const results = await Promise.allSettled([
tools.exec_command({cmd:"cat AGENTS.md && cat .gitignore && entire agent-help status && git log -1 --format='%h %s' && git ls-files --others --exclude-standard && git ls-files --others --ignored --exclude-standard --directory && ps -axo pid,command | rg 'software-factory|node (factory|control|orchestrator)|sprite'","max_output_tokens":5000}),
tools.web__run({open:[{ref_id:"https://raw.githubusercontent.com/aaif-goose/goosetown/main/goose"},{ref_id:"https://raw.githubusercontent.com/aaif-goose/goosetown/main/AGENTS.md"},{ref_id:"https://docs.sprites.dev/"}],response_length:"long"})
]); results.forEach((r,i)=>text({i,...r}));

text(await tools.exec_command({cmd:"open 'https://sprites.dev/oauth/authorize?response_type=code&REDACTED&state=zwAwOsEiMj0cop0qc9Hiow&REDACTED&code_challenge_method=S256&redirect_uri=http%3A%2F%2F127.0.0.1%3A65074%2Fcallback%2FvyhoGvz_wc9d&scope=sprites%3Aread+sprites%3Awrite&resource=https%3A%2F%2Fsprites.dev%2Fmcp'","max_output_tokens":1000}));
text(await tools.exec_command({cmd:"codex mcp get sprites","max_output_tokens":1000}));
text(await tools.write_stdin({session_id:57133,chars:"","yield_time_ms":1000,"max_output_tokens":1000}));

text(ALL_TOOLS.filter(x=>/sprite/i.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,300)})));
text(await tools.exec_command({cmd:"pwd && git status --short && ls -la && codex --version && codex exec --help && codex app-server --help","max_output_tokens":5000}));
text(await tools.web__run({search_query:[{q:"Codex low cost model reasoning low",domains:["developers.openai.com","learn.chatgpt.com"]}],response_length:"short"}));

const results=await Promise.allSettled([
tools.exec_command({cmd:"codex app-server generate-json-schema --help && codex mcp get sprites && entire agent-help && cat /Users/rizelscarlett/.codex/skills/.system/openai-docs/references/model-selection.md","max_output_tokens":6500}),
tools.web__run({open:[{ref_id:"https://developers.openai.com/api/docs/models/gpt-5.6-luna"},{ref_id:"https://developers.openai.com/api/docs/models/gpt-6-luna"},{ref_id:"https://developers.openai.com/api/docs/guides/reasoning"},{ref_id:"https://github.com/superfly/sprites-mcp"}],response_length:"short"})
]);results.forEach((r,i)=>text({i,...r}));

text(await tools.exec_command({cmd:"codex app-server generate-json-schema --experimental --out /tmp/software-factory-codex-schema && python3 - <<'PY'
import json
from pathlib import Path
p=Path('/tmp/software-factory-codex-schema')
for f in p.rglob('*Mcp*'):
 print(f)
f=p/'ClientRequest.json'
s=f.read_text()
d=json.loads(s)
for x in d.get('oneOf',[]):
 if 'mcp' in json.dumps(x).lower() or 'model/list' in json.dumps(x): print(json.dumps(x))
PY","max_output_tokens":4000}));
text(await tools.web__run({find:[{ref_id:"turn12view0",pattern:"$"},{ref_id:"turn12view1",pattern:"$"}],response_length:"short"}));

