p=subprocess.Popen(['codex','app-server','--stdio'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True,bufsize=1)
q=queue.Queue()
def read():
 for line in p.stdout:
  try:q.put(json.loads(line))
  except ValueError:pass
