import json, subprocess, sys, threading, queue, time
p=subprocess.Popen(['codex','app-server','--stdio'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True,bufsize=1)
q=queue.Queue()
def read():
 for line in p.stdout:
  try:q.put(json.loads(line))
  except ValueError:pass
threading.Thread(target=read,daemon=True).start()
i=0
def rpc(method,params):
 global i
 i+=1; rid=i
 p.stdin.write(json.dumps({'id':rid,'method':method,'params':params})+'\n');p.stdin.flush()
 deadline=time.monotonic()+180
 while time.monotonic()<deadline:
  msg=q.get(timeout=max(.1,deadline-time.monotonic()))
  if msg.get('id')==rid:
   if 'error' in msg:raise RuntimeError(json.dumps(msg['error']))
   return msg.get('result')
  if 'id' in msg and 'method' in msg:
   p.stdin.write(json.dumps({'id':msg['id'],'error':{'code':-32601,'message':'Interactive requests are not supported by this bridge'}})+'\n');p.stdin.flush()
 raise TimeoutError(method)
try:
 rpc('initialize',{'clientInfo':{'name':'software_factory_setup','version':'0.1.0'},'capabilities':{'experimentalApi':True}})
 p.stdin.write('{"method":"initialized"}\n');p.stdin.flush()
 action=sys.argv[1]
 if action=='models':result=rpc('model/list',{'includeHidden':True})
 else:
  t=rpc('thread/start',{'ephemeral':True,'cwd':'/tmp','model':'gpt-6-luna','config':{'model_reasoning_effort':'low'},'approvalPolicy':'never','sandbox':'read-only'})
  tid=t['thread']['id']
  status=rpc('mcpServerStatus/list',{'threadId':tid})
  if action=='tools':result=[s for s in status['data'] if s['name']=='sprites']
  else:result=rpc('mcpServer/tool/call',{'threadId':tid,'server':'sprites','tool':action,'arguments':json.loads(sys.argv[2])})
 print(json.dumps(result,indent=2))
finally:
 p.terminate()
 try:p.wait(timeout=5)
 except subprocess.TimeoutExpired:p.kill()

