  { note: 'B4', name: 'B', frequency: 493.88, key: 'j' },
  { note: 'C5', name: 'C', frequency: 523.25, key: 'k' },
];

export const CHORDS = {
  C: ['C4', 'E4', 'G4'],
  Am: ['A4', 'C5', 'E4'],
  F: ['F4', 'A4', 'C5'],
  G: ['G4', 'B4', 'D4'],
};

export function noteByName(noteName) {
  return NOTES.find((note) => note.note === noteName) ?? null;
}

export function chordNotes(chordName) {
  return (CHORDS[chordName] ?? []).map(noteByName).filter(Boolean);
}

export function frequencyFor(noteName) {
  return noteByName(noteName)?.frequency ?? 0;
}

import { NOTES } from './music.js';

export function keyForPoint(x, y, mirrored = true) {
  const mappedX = mirrored ? 1 - x : x;
  if (mappedX < 0 || mappedX >= 1 || y < 0 || y > 1) return null;
  return NOTES[Math.min(NOTES.length - 1, Math.floor(mappedX * NOTES.length))];
}

export function pinchDistance(hand) {
  const thumb = hand?.[4];
  const index = hand?.[8];
  if (!thumb || !index) return Infinity;
  return Math.hypot(thumb.x - index.x, thumb.y - index.y);
}

export function handScale(hand) {
  const wrist = hand?.[0];
  const middle = hand?.[9];
  if (!wrist || !middle) return 1;
  return Math.max(.04, Math.hypot(wrist.x - middle.x, wrist.y - middle.y));
}

export class PinchGate {
  constructor(closeRatio = .42, openRatio = .62) {
    this.closeRatio = closeRatio;
    this.openRatio = openRatio;
    this.pressed = false;
  }

  update(hand) {
    if (!hand) return { down: false, pressed: this.pressed };
    const ratio = pinchDistance(hand) / handScale(hand);
    if (!this.pressed && ratio <= this.closeRatio) {
      this.pressed = true;
      return { down: true, pressed: true };
    }
    if (this.pressed && ratio >= this.openRatio) this.pressed = false;
    return { down: false, pressed: this.pressed };
  }

  reset() { this.pressed = false; }
}

export function resetTracking(gates) {
  gates.forEach((gate) => gate.reset());
  return gates;
}

export const EXERCISE = ['C', 'Am', 'F', 'G'];

export class ExerciseProgress {
  constructor(sequence = EXERCISE) {
    this.sequence = sequence;
    this.restart();
  }

  input(chord) {
    if (this.complete || chord !== this.sequence[this.index]) return false;
    this.index += 1;
    this.complete = this.index === this.sequence.length;
    return true;
  }

  restart() {
    this.index = 0;
    this.complete = false;
  }

  get next() { return this.sequence[this.index] ?? null; }
  get progress() { return this.index / this.sequence.length; }
}

