import { CHORDS, NOTES, chordNotes, noteByName } from './music.js';
import { ExerciseProgress } from './exercise.js';
import { PinchGate, keyForPoint, resetTracking } from './interaction.js';

const MEDIAPIPE_VERSION = '0.10.22-0';
const MODEL_URL = 'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task';
const WASM_URL = `https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@${MEDIAPIPE_VERSION}/wasm`;
const VISION_URL = `https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@${MEDIAPIPE_VERSION}`;
const $ = (id) => document.getElementById(id);
const keyboard = $('keyboard');
const exercise = new ExerciseProgress();
const gates = [new PinchGate(), new PinchGate()];
let selectedChord = 'C';
let chordMode = false;
let muted = false;
let audioContext;
let masterGain;
let activeVoices = new Set();
let cameraStream;
let handLandmarker;
let animationFrame;
let cameraRun = 0;
let lastVideoTime = -1;

function renderKeyboard() {
  keyboard.innerHTML = NOTES.map((note) => `<button class="key" data-note="${note.note}" data-key="${note.key}" type="button" aria-label="${note.name} note, computer key ${note.key.toUpperCase()}"><strong>${note.name}</strong><small>${note.key.toUpperCase()}</small></button>`).join('');
}

function ensureAudio() {
  audioContext ??= new AudioContext();
  masterGain ??= audioContext.createGain();
  if (!masterGain._connected) { masterGain.connect(audioContext.destination); masterGain._connected = true; }
  masterGain.gain.value = muted ? 0 : Number($('volume').value);
  if (audioContext.state === 'suspended') audioContext.resume();
}

function playTone(note, when = audioContext.currentTime, duration = 1.05) {
  if (!note || !audioContext || muted) return;
  const voice = audioContext.createGain();
  const osc = audioContext.createOscillator();
  const shimmer = audioContext.createOscillator();
  const shimmerGain = audioContext.createGain();
  osc.type = 'triangle'; shimmer.type = 'sine';
  osc.frequency.value = note.frequency; shimmer.frequency.value = note.frequency * 2.01;
  shimmerGain.gain.value = .12;
  voice.gain.setValueAtTime(0.0001, when);
  voice.gain.exponentialRampToValueAtTime(.28 / Math.max(1, activeVoices.size), when + .012);
  voice.gain.exponentialRampToValueAtTime(.0001, when + duration);
  osc.connect(voice); shimmer.connect(shimmerGain); shimmerGain.connect(voice); voice.connect(masterGain);
  osc.start(when); shimmer.start(when); osc.stop(when + duration + .04); shimmer.stop(when + duration + .04);
  activeVoices.add(voice); voice.addEventListener('ended', () => activeVoices.delete(voice), { once: true });
  while (activeVoices.size > 12) activeVoices.values().next().value.gain.setTargetAtTime(.0001, when, .01);
}

function stopSound() {
  activeVoices.forEach((voice) => { try { voice.gain.cancelScheduledValues(audioContext?.currentTime ?? 0); voice.gain.setTargetAtTime(.0001, audioContext?.currentTime ?? 0, .01); } catch {} });
  activeVoices.clear();
  document.querySelectorAll('.key.is-active').forEach((key) => key.classList.remove('is-active'));
  $('now-playing').textContent = '—'; $('playing-detail').textContent = 'Choose a key or chord to begin'; $('tone-pills').replaceChildren();
}

function showPlaying(note, isChord = chordMode) {
  const tones = isChord ? chordNotes(selectedChord) : [note];
  $('now-playing').textContent = isChord ? selectedChord : note.name;
  $('playing-detail').textContent = isChord ? `${tones.map((tone) => tone.name).join(' · ')} · chord assistance` : `${note.name} major scale`;
  $('tone-pills').innerHTML = tones.map((tone) => `<span class="tone-pill">${tone.name}</span>`).join('');
  document.querySelectorAll('.key.is-active').forEach((key) => key.classList.remove('is-active'));
  tones.forEach((tone) => document.querySelector(`[data-note="${tone.note}"]`)?.classList.add('is-active'));
}

function playNote(note) {
  ensureAudio();
  const tones = chordMode ? chordNotes(selectedChord) : [note];
  tones.forEach((tone) => playTone(tone));
  showPlaying(note); exercise.input(chordMode ? selectedChord : note.name); renderExercise();
}

function renderExercise() {
  $('exercise-next').textContent = exercise.complete ? 'Loop complete — restart for another round' : `Next target: ${exercise.next}`;
  $('exercise-progress').style.width = `${exercise.progress * 100}%`;
  $('exercise-complete').hidden = !exercise.complete;
}

function triggerRipple(element) { const ripple = document.createElement('span'); ripple.className = 'ripple'; ripple.style.left = `${element.offsetLeft + element.offsetWidth / 2 - 17}px`; ripple.style.top = `${element.offsetTop + 48}px`; keyboard.append(ripple); ripple.addEventListener('animationend', () => ripple.remove()); }

function selectChord(name) { selectedChord = name; document.querySelectorAll('.chord-button').forEach((button) => button.classList.toggle('selected', button.dataset.chord === name)); }

function setCameraStatus(text, state = 'idle') { const status = $('camera-status'); status.textContent = text; status.dataset.state = state; }

async function startCamera() {
  if (!navigator.mediaDevices?.getUserMedia) { setCameraStatus('Unsupported', 'error'); $('camera-message').textContent = 'This browser does not provide webcam access. Manual keys still work.'; return; }
  const run = ++cameraRun; $('camera-button').disabled = true; setCameraStatus('Loading model…', 'working'); $('camera-message').textContent = 'Loading the hand model locally in your browser…';
  try {
    cameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false });
    if (run !== cameraRun) return;
    const vision = await import(VISION_URL);
    handLandmarker = await vision.HandLandmarker.createFromOptions(await vision.FilesetResolver.forVisionTasks(WASM_URL), { baseOptions: { modelAssetPath: MODEL_URL, delegate: 'GPU' }, runningMode: 'VIDEO', numHands: 2, minHandDetectionConfidence: .55, minHandPresenceConfidence: .55, minTrackingConfidence: .5 });
    if (run !== cameraRun) return;
    const video = $('camera-video'); video.srcObject = cameraStream; await video.play(); video.dataset.active = 'true'; $('camera-empty').hidden = true; $('camera-button').textContent = 'Stop camera'; $('camera-button').disabled = false; setCameraStatus('Tracking', 'working'); $('camera-message').textContent = 'Point at a key, pinch thumb + index, then release to play again.'; trackFrame(run);
  } catch (error) {
    stopCamera(false); $('camera-button').disabled = false; setCameraStatus(error?.name === 'NotAllowedError' ? 'Permission needed' : 'Unavailable', 'error'); $('camera-message').textContent = error?.name === 'NotAllowedError' ? 'Camera permission was denied. Allow access in the browser, then retry — manual play remains available.' : 'The camera or hand model could not start. Check your connection and retry; manual play remains available.';
  }
}

function trackFrame(run) {
  if (run !== cameraRun || !handLandmarker) return;
  const video = $('camera-video');
  if (video.readyState >= 2 && video.currentTime !== lastVideoTime) {
    lastVideoTime = video.currentTime;
    const result = handLandmarker.detectForVideo(video, performance.now());
    const hands = result.landmarks ?? [];
    if (!hands.length) resetTracking(gates);
    hands.forEach((hand, index) => { const tip = hand[8]; const target = keyForPoint(tip.x, tip.y, true); const pinch = gates[index].update(hand); if (pinch.down && target) { playNote(target); triggerRipple(document.querySelector(`[data-note="${target.note}"]`)); } drawHand(hand); });
  }
  animationFrame = requestAnimationFrame(() => trackFrame(run));
}

function drawHand(hand) { const canvas = $('camera-overlay'); const view = $('camera-view'); const rect = view.getBoundingClientRect(); canvas.width = rect.width; canvas.height = rect.height; const ctx = canvas.getContext('2d'); const tip = hand[8]; ctx.fillStyle = '#e66c66'; ctx.beginPath(); ctx.arc((1 - tip.x) * canvas.width, tip.y * canvas.height, 10, 0, Math.PI * 2); ctx.fill(); }

function stopCamera(update = true) { cameraRun += 1; cancelAnimationFrame(animationFrame); resetTracking(gates); cameraStream?.getTracks().forEach((track) => track.stop()); cameraStream = null; handLandmarker?.close?.(); handLandmarker = null; const video = $('camera-video'); video.pause(); video.srcObject = null; video.dataset.active = 'false'; $('camera-empty').hidden = false; $('camera-button').textContent = 'Start camera'; $('camera-button').disabled = false; if (update) { setCameraStatus('Ready'); $('camera-message').textContent = 'Camera stopped. Manual play is still ready.'; } }

function setupGuide() { $('guide-size').addEventListener('input', (event) => $('guide-overlay').style.width = `${event.target.value}%`); $('guide-x').addEventListener('input', (event) => $('guide-overlay').style.left = `${event.target.value}%`); $('guide-y').addEventListener('input', (event) => $('guide-overlay').style.top = `${event.target.value}%`); }

renderKeyboard(); renderExercise(); setupGuide();
keyboard.addEventListener('pointerdown', (event) => { const key = event.target.closest('.key'); if (key) { const note = noteByName(key.dataset.note); playNote(note); key.classList.add('is-coral'); triggerRipple(key); } });
document.addEventListener('pointerup', () => document.querySelectorAll('.key.is-coral').forEach((key) => key.classList.remove('is-coral')));
document.addEventListener('keydown', (event) => { if (event.repeat) return; const note = NOTES.find((candidate) => candidate.key === event.key.toLowerCase()); if (note) { playNote(note); document.querySelector(`[data-note="${note.note}"]`)?.classList.add('is-coral'); } });
document.addEventListener('keyup', (event) => { const note = NOTES.find((candidate) => candidate.key === event.key.toLowerCase()); if (note) document.querySelector(`[data-note="${note.note}"]`)?.classList.remove('is-coral'); });
document.querySelectorAll('.chord-button').forEach((button) => button.addEventListener('click', () => selectChord(button.dataset.chord)));
$('mode-toggle').addEventListener('click', () => { chordMode = !chordMode; $('mode-toggle').textContent = chordMode ? 'Chords' : 'Notes'; $('mode-toggle').setAttribute('aria-pressed', String(chordMode)); });
$('volume').addEventListener('input', (event) => { if (masterGain) masterGain.gain.value = muted ? 0 : Number(event.target.value); });
$('tempo').addEventListener('input', (event) => { $('tempo-value').value = event.target.value; $('tempo-value').textContent = event.target.value; });
$('mute-button').addEventListener('click', () => { muted = !muted; $('mute-button').textContent = muted ? 'Unmute' : 'Mute'; $('mute-button').setAttribute('aria-pressed', String(muted)); if (masterGain) masterGain.gain.value = muted ? 0 : Number($('volume').value); });
$('stop-button').addEventListener('click', () => { stopSound(); stopCamera(); });
$('camera-button').addEventListener('click', () => cameraStream ? stopCamera() : startCamera());
$('exercise-restart').addEventListener('click', () => { exercise.restart(); renderExercise(); });
$('air-tab').addEventListener('click', () => { $('air-tab').classList.add('active'); $('guide-tab').classList.remove('active'); $('air-tab').setAttribute('aria-selected', 'true'); $('guide-tab').setAttribute('aria-selected', 'false'); $('air-panel').hidden = false; $('guide-panel').hidden = true; });
$('guide-tab').addEventListener('click', async () => { $('guide-tab').classList.add('active'); $('air-tab').classList.remove('active'); $('guide-tab').setAttribute('aria-selected', 'true'); $('air-tab').setAttribute('aria-selected', 'false'); $('air-panel').hidden = true; $('guide-panel').hidden = false; if (!cameraStream && navigator.mediaDevices?.getUserMedia) { try { cameraStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false }); $('guide-video').srcObject = cameraStream; await $('guide-video').play(); $('guide-video').dataset.active = 'true'; } catch { $('guide-video').dataset.active = 'false'; } } });

window.addEventListener('beforeunload', () => { stopCamera(false); stopSound(); });

export { keyForPoint };

