import test from 'node:test';
import assert from 'node:assert/strict';
import { CHORDS, frequencyFor, chordNotes } from './music.js';
import { PinchGate, keyForPoint, resetTracking } from './interaction.js';
import { ExerciseProgress } from './exercise.js';

const hand = (distance) => {
  const points = Array.from({ length: 21 }, () => ({ x: 0, y: 0 }));
  points[0] = { x: .5, y: .8 }; points[9] = { x: .5, y: .4 };
  points[4] = { x: .5, y: .5 }; points[8] = { x: .5 + distance, y: .5 };
  return points;
};

test('frequencies and chord tone mappings are musical and complete', () => {
  assert.equal(frequencyFor('A4'), 440);
  assert.deepEqual(chordNotes('C').map((note) => note.name), ['C', 'E', 'G']);
  assert.deepEqual(Object.keys(CHORDS), ['C', 'Am', 'F', 'G']);
});

test('mirrored key hit regions include bounds and reject outside points', () => {
  assert.equal(keyForPoint(.01, .5, true).name, 'C');
  assert.equal(keyForPoint(.99, .5, true).name, 'C');
  assert.equal(keyForPoint(.01, .5, false).name, 'C');
  assert.equal(keyForPoint(1.01, .5, true), null);
  assert.equal(keyForPoint(.5, -0.01, true), null);
});

test('pinch gate triggers once and requires release before retrigger', () => {
  const gate = new PinchGate();
  assert.equal(gate.update(hand(.05)).down, true);
  assert.equal(gate.update(hand(.05)).down, false);
  assert.equal(gate.update(hand(.07)).down, false);
  assert.equal(gate.update(hand(.2)).pressed, false);
  assert.equal(gate.update(hand(.05)).down, true);
});

test('tracking reset releases pinch state', () => {
  const gate = new PinchGate(); gate.update(hand(.05));
  resetTracking([gate]);
  assert.equal(gate.update(hand(.05)).down, true);
});

test('exercise only advances on the correct real input and can restart', () => {
  const exercise = new ExerciseProgress();
  assert.equal(exercise.input('Am'), false);
  for (const chord of ['C', 'Am', 'F', 'G']) assert.equal(exercise.input(chord), true);
  assert.equal(exercise.complete, true);
  exercise.restart();
  assert.equal(exercise.next, 'C');
  assert.equal(exercise.progress, 0);
});
