import { NOTES, chordNotes, noteByName } from './music.js';
import { ExerciseProgress } from './exercise.js';
import { PinchGate, keyForPoint, resetTracking } from './interaction.js';

const VISION_URL='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs', WASM_URL='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm', MODEL_URL='https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task';
const $=id=>document.getElementById(id), keyboard=$('keyboard'), exercise=new ExerciseProgress(), gates=new Map(); let selectedChord='C', chordMode=false, muted=false, audioContext, masterGain, cameraStream, handLandmarker, animationFrame, cameraRun=0, lastVideoTime=-1, lastInference=0, rhythmTimer, rhythmBeat=0; const activeVoices=new Set(), VOICE_LIMIT=12;
function renderKeyboard(){keyboard.innerHTML=NOTES.map(n=>`<button class="key" data-note="${n.note}" data-key="${n.key}" type="button" aria-label="${n.name} ${n.note}, computer key ${n.key.toUpperCase()}"><strong>${n.name}</strong><small>${n.key.toUpperCase()}</small></button>`).join('')}
function ensureAudio(){audioContext??=new AudioContext();masterGain??=audioContext.createGain();if(!masterGain._connected){masterGain.connect(audioContext.destination);masterGain._connected=true}masterGain.gain.value=muted?0:Number($('volume').value);if(audioContext.state==='suspended')audioContext.resume()}
function playTone(note,when=audioContext.currentTime,duration=1.05){if(!note||!audioContext||muted)return;while(activeVoices.size>=VOICE_LIMIT)activeVoices.values().next().value.stop();const v={gain:audioContext.createGain(),osc:audioContext.createOscillator(),shimmer:audioContext.createOscillator(),shimmerGain:audioContext.createGain(),stopped:false};v.osc.type='triangle';v.shimmer.type='sine';v.osc.frequency.value=note.frequency;v.shimmer.frequency.value=note.frequency*2.01;v.shimmerGain.gain.value=.12;v.gain.gain.setValueAtTime(.0001,when);v.gain.gain.exponentialRampToValueAtTime(.28/Math.max(1,activeVoices.size),when+.012);v.gain.gain.exponentialRampToValueAtTime(.0001,when+duration);v.osc.connect(v.gain);v.shimmer.connect(v.shimmerGain);v.shimmerGain.connect(v.gain);v.gain.connect(masterGain);const clean=()=>{if(v.stopped)return;v.stopped=true;activeVoices.delete(v);[v.osc,v.shimmer,v.gain,v.shimmerGain].forEach(n=>{try{n.disconnect()}catch{}})};v.osc.addEventListener('ended',clean,{once:true});v.shimmer.addEventListener('ended',clean,{once:true});v.stop=()=>{if(v.stopped)return;try{v.osc.stop();v.shimmer.stop()}catch{}clean()};v.osc.start(when);v.shimmer.start(when);v.osc.stop(when+duration+.04);v.shimmer.stop(when+duration+.04);activeVoices.add(v)}
function stopRhythm(){clearInterval(rhythmTimer);rhythmTimer=null} function stopSound(){activeVoices.forEach(v=>v.stop());activeVoices.clear();document.querySelectorAll('.key.is-active').forEach(k=>k.classList.remove('is-active'));$('now-playing').textContent='—';$('playing-detail').textContent='Choose a key or chord to begin';$('tone-pills').replaceChildren();stopRhythm()}
function showPlaying(note,chord=chordMode?selectedChord:null){const tones=chord?chordNotes(chord):[note];$('now-playing').textContent=chord??note.note;$('playing-detail').textContent=chord?`${tones.map(t=>t.note).join(' · ')} · chord assistance`:`${note.note} · single note`;$('tone-pills').innerHTML=tones.map(t=>`<span class="tone-pill">${t.note}</span>`).join('');document.querySelectorAll('.key.is-active').forEach(k=>k.classList.remove('is-active'));tones.forEach(t=>document.querySelector(`[data-note="${t.note}"]`)?.classList.add('is-active'))}
function renderExercise(){$('exercise-next').textContent=exercise.complete?'Loop complete — restart for another round':`Next target: ${exercise.next}`;$('exercise-progress').style.width=`${exercise.progress*100}%`;$('exercise-complete').hidden=!exercise.complete} function ripple(el){const r=document.createElement('span');r.className='ripple';r.style.left=`${el.offsetLeft+el.offsetWidth/2-17}px`;r.style.top=`${el.offsetTop+48}px`;keyboard.append(r);r.addEventListener('animationend',()=>r.remove())}
function playChord(name=selectedChord){ensureAudio();chordNotes(name).forEach(t=>playTone(t));selectedChord=name;showPlaying(chordNotes(name)[0],name);exercise.input(name);renderExercise()} function playNote(note){ensureAudio();if(chordMode)return playChord();playTone(note);showPlaying(note)} function selectChord(name,audition=true){selectedChord=name;document.querySelectorAll('.chord-button').forEach(b=>b.classList.toggle('selected',b.dataset.chord===name));if(audition)playChord(name)} function status(text,state='idle'){$('camera-status').textContent=text;$('camera-status').dataset.state=state}
function guideOverlay(){$('guide-overlay').innerHTML=NOTES.map(n=>`<span data-note="${n.note}">${n.note}</span>`).join('')} function draw(hands=[],targets=[]){const c=$('camera-overlay'),r=$('camera-view').getBoundingClientRect();c.width=r.width;c.height=r.height;const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.font='bold 12px system-ui';for(let i=0;i<NOTES.length;i++){const left=i*c.width/NOTES.length;x.fillStyle='rgba(255,255,255,.14)';x.fillRect(left,c.height*.62,c.width/NOTES.length,c.height*.38);x.strokeStyle='rgba(255,255,255,.8)';x.strokeRect(left,c.height*.62,c.width/NOTES.length,c.height*.38);x.fillStyle='#fff';x.fillText(NOTES[i].note,left+6,c.height*.94)}targets.forEach(t=>{x.strokeStyle='#e66c66';x.lineWidth=3;x.strokeRect(t.x*c.width-3,c.height*.62,c.width/NOTES.length+6,c.height*.38)});hands.forEach(h=>{const t=h[8];x.fillStyle='#e66c66';x.beginPath();x.arc((1-t.x)*c.width,t.y*c.height,9,0,Math.PI*2);x.fill()})}
async function startCamera(){ensureAudio();if(!navigator.mediaDevices?.getUserMedia){status('Unsupported','error');$('camera-message').textContent='Webcam unavailable. Manual keys still work.';return}const run=++cameraRun;$('camera-button').disabled=true;status('Loading model…','working');try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}},audio:false});if(run!==cameraRun)return stream.getTracks().forEach(t=>t.stop());cameraStream=stream;const vision=await import(VISION_URL);handLandmarker=await vision.HandLandmarker.createFromOptions(await vision.FilesetResolver.forVisionTasks(WASM_URL),{baseOptions:{modelAssetPath:MODEL_URL,delegate:'GPU'},runningMode:'VIDEO',numHands:2,minHandDetectionConfidence:.55,minHandPresenceConfidence:.55,minTrackingConfidence:.5});if(run!==cameraRun)return stopCamera(false);for(const id of ['camera-video','guide-video']){const v=$(id);v.srcObject=stream;v.dataset.active='true';await v.play()}$('camera-empty').hidden=true;$('camera-button').textContent='Stop camera';$('camera-button').disabled=false;status('Tracking','working');$('camera-message').textContent='Pinch thumb + index over a labeled zone to play.';track(run)}catch(e){stopCamera(false);$('camera-button').disabled=false;status(e?.name==='NotAllowedError'?'Permission needed':'Unavailable','error');$('camera-message').textContent='Camera or hand model unavailable. Retry, or use the manual keyboard.'}}
function track(run){if(run!==cameraRun||!handLandmarker)return;const v=$('camera-video');if(v.readyState>=2&&v.currentTime!==lastVideoTime&&performance.now()-lastInference>=1000/15){lastVideoTime=v.currentTime;lastInference=performance.now();try{const result=handLandmarker.detectForVideo(v,lastInference),hands=result.landmarks??[],targets=[],seen=new Set();hands.forEach((h,i)=>{const id=result.handednesses?.[i]?.[0]?.categoryName??`hand-${i}`;seen.add(id);const gate=gates.get(id)??new PinchGate();gates.set(id,gate);const t=h[8],note=keyForPoint(t.x,t.y,true);if(note)targets.push({x:1-t.x,note:note.note});if(gate.update(h).down&&note){if(chordMode)playChord();else playNote(note);ripple(document.querySelector(`[data-note="${note.note}"]`))}});gates.forEach((g,id)=>{if(!seen.has(id))g.reset()});draw(hands,targets);$('guide-overlay').querySelectorAll('[data-note]').forEach(e=>e.classList.toggle('target',targets.some(t=>t.note===e.dataset.note)))}catch{status('Tracking paused','error')}}animationFrame=requestAnimationFrame(()=>track(run))}
function stopCamera(update=true){cameraRun++;cancelAnimationFrame(animationFrame);resetTracking([...gates.values()]);gates.clear();cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;handLandmarker?.close?.();handLandmarker=null;['camera-video','guide-video'].forEach(id=>{const v=$(id);v.pause();v.srcObject=null;v.dataset.active='false'});$('camera-overlay').getContext('2d')?.clearRect(0,0,$('camera-overlay').width,$('camera-overlay').height);$('camera-empty').hidden=false;$('camera-button').textContent='Start camera';$('camera-button').disabled=false;if(update){status('Ready');$('camera-message').textContent='Camera stopped. Manual play is still ready.'}}
function startRhythm(){stopRhythm();if(!$('rhythm-toggle').checked||muted)return;const tick=()=>{playTone(noteByName(rhythmBeat++%4===0?'C4':'G4'),audioContext.currentTime,rhythmBeat%4===1?.12:.07)};tick();rhythmTimer=setInterval(tick,60000/Number($('tempo').value)/2)}
renderKeyboard();renderExercise();guideOverlay();$('guide-size').addEventListener('input',e=>$('guide-overlay').style.width=`${e.target.value}%`);$('guide-x').addEventListener('input',e=>$('guide-overlay').style.left=`${e.target.value}%`);$('guide-y').addEventListener('input',e=>$('guide-overlay').style.top=`${e.target.value}%`);keyboard.addEventListener('pointerdown',e=>{const k=e.target.closest('.key');if(k){playNote(noteByName(k.dataset.note));k.classList.add('is-coral');ripple(k)}});document.addEventListener('pointerup',()=>document.querySelectorAll('.key.is-coral').forEach(k=>k.classList.remove('is-coral')));document.addEventListener('keydown',e=>{if(e.repeat||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName))return;const n=NOTES.find(n=>n.key===e.key.toLowerCase());if(n){e.preventDefault();playNote(n);document.querySelector(`[data-note="${n.note}"]`)?.classList.add('is-coral')}});document.addEventListener('keyup',e=>{const n=NOTES.find(n=>n.key===e.key.toLowerCase());if(n)document.querySelector(`[data-note="${n.note}"]`)?.classList.remove('is-coral')});document.querySelectorAll('.chord-button').forEach(b=>b.addEventListener('click',()=>selectChord(b.dataset.chord)));$('mode-toggle').addEventListener('click',()=>{chordMode=!chordMode;$('mode-toggle').textContent=chordMode?'Chords':'Notes';$('mode-toggle').setAttribute('aria-pressed',String(chordMode))});$('volume').addEventListener('input',e=>{if(masterGain)masterGain.gain.value=muted?0:Number(e.target.value)});$('tempo').addEventListener('input',e=>{$('tempo-value').textContent=e.target.value;startRhythm()});$('rhythm-toggle').addEventListener('change',()=>{ensureAudio();startRhythm()});$('mute-button').addEventListener('click',()=>{muted=!muted;$('mute-button').textContent=muted?'Unmute':'Mute';if(masterGain)masterGain.gain.value=muted?0:Number($('volume').value);muted?stopRhythm():startRhythm()});$('stop-button').addEventListener('click',()=>{stopSound();stopCamera()});$('camera-button').addEventListener('click',()=>cameraStream?stopCamera():startCamera());$('exercise-restart').addEventListener('click',()=>{exercise.restart();renderExercise()});$('guide-tab').addEventListener('click',()=>{ $('guide-tab').classList.add('active');$('air-tab').classList.remove('active');$('guide-tab').setAttribute('aria-selected','true');$('air-tab').setAttribute('aria-selected','false');$('air-panel').hidden=true;$('guide-panel').hidden=false});$('air-tab').addEventListener('click',()=>{ $('air-tab').classList.add('active');$('guide-tab').classList.remove('active');$('air-tab').setAttribute('aria-selected','true');$('guide-tab').setAttribute('aria-selected','false');$('air-panel').hidden=false;$('guide-panel').hidden=true});window.addEventListener('beforeunload',()=>{stopCamera(false);stopSound()});export{keyForPoint};

