(async()=>{
 const $=id=>document.getElementById(id),checks=[],delay=ms=>new Promise(r=>setTimeout(r,ms));
 const check=(name,pass)=>checks.push({name,pass:!!pass});
 for(let i=0;i<40&&$('camera-status').textContent!=='Tracking';i++)await delay(250);
 check('Real MediaPipe model starts with synthetic camera',$('camera-status').textContent==='Tracking');
 if($('camera-status').textContent!=='Tracking')return JSON.stringify(checks);
 const vision=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');
 const proto=vision.HandLandmarker.prototype,detect=proto.detectForVideo;
 let hand=null;
 const make=(x,y,closed=true)=>{const h=Array.from({length:21},()=>({x:.5,y:.5,z:0}));h[0]={x:.5,y:.6};h[9]={x:.5,y:.3};h[8]={x,y};h[4]={x:closed?x-.005:x-.3,y};return h;};
 proto.detectForVideo=()=>({landmarks:hand?[hand]:[],handedness:hand?[[{categoryName:'Right'}]]:[],handednesses:hand?[[{categoryName:'Right'}]]:[]});
 try{
  await delay(200);hand=make(.95,.8);await delay(250);
  check('Simulated pinch plays visible C4 zone',$('now-playing').textContent==='C4');
  hand=make(.7,.8);await delay(250);
  check('Held pinch does not retrigger another note',$('now-playing').textContent==='C4');
  hand=make(.7,.8,false);await delay(200);hand=make(.7,.8);await delay(250);
  check('Release and pinch plays next E4 zone',$('now-playing').textContent==='E4');
  hand=null;await delay(200);$('now-playing').textContent='outside-zone';hand=make(.7,.3);await delay(250);
  check('Pinch outside visible zones makes no note',$('now-playing').textContent==='outside-zone');
  $('guide-tab').click();document.querySelector('.chord-button[data-chord="C"]').click();
  hand=make(.7,.8,false);await delay(200);hand=make(.7,.8);await delay(250);
  check('Guide pinch does not play air notes',$('now-playing').textContent==='C');
  const c=$('guide-overlay-canvas'),pixel=c.getContext('2d').getImageData(Math.floor(.3*c.width),Math.floor(.8*c.height),1,1).data;
  check('Guide fingertip marker is drawn',pixel[3]>0);
  check('Guide copy hidden with active camera',document.querySelector('.guide-copy').hidden);
  check('Both camera buttons show Stop',[$('camera-button'),$('guide-camera-button')].every(b=>b.textContent==='Stop camera'));
 }finally{proto.detectForVideo=detect;$('stop-button').click();}
 check('Stop releases both videos',[$('camera-video'),$('guide-video')].every(v=>v.srcObject===null));
 $('air-tab').click();
 return JSON.stringify(checks);
})()
